diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 15:27:46.402939798 +0000
@@ -0,0 +1,173 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function viaStream(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) rows.push(...s.push(chunk));
+  rows.push(...s.end());
+  return rows;
+}
+
+function thrown(f: () => unknown): unknown {
+  try {
+    f();
+  } catch (e) {
+    return e;
+  }
+  throw new Error("nothing was thrown");
+}
+
+function splitAt(text: string, cuts: number[]): string[] {
+  const chunks: string[] = [];
+  let from = 0;
+  for (const cut of [...cuts, text.length]) {
+    chunks.push(text.slice(from, cut));
+    from = cut;
+  }
+  return chunks;
+}
+
+function expectSameAsParse(text: string, chunks: string[]) {
+  let expected: string[][];
+  try {
+    expected = parseCsv(text);
+  } catch {
+    expect(() => viaStream(chunks)).toThrow(SyntaxError);
+    return;
+  }
+  expect(viaStream(chunks)).toEqual(expected);
+}
+
+function mulberry32(seed: number) {
+  return () => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+const ALPHABET = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+
+test("every single cut of a plain input gives the parseCsv rows", () => {
+  const text = "a,b\r\nc\n";
+  for (let cut = 0; cut <= text.length; cut++) expectSameAsParse(text, splitAt(text, [cut]));
+});
+
+test("a lone \\r stays in its field, also across a chunk edge", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("b")).toEqual([]);
+  expect(s.end()).toEqual([["a\rb"]]);
+  expect(viaStream(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a row comes out as soon as its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\n")).toEqual([["a"]]);
+  expect(new CsvStream().push("a\n")).toEqual([["a"]]);
+});
+
+test("quoted fields keep , \\r and \\n, and a doubled quote becomes one quote, also when split", () => {
+  expect(viaStream(['"a,\r\n""', 'b"', "\n"])).toEqual([['a,\r\n"b']]);
+  expect(viaStream(['"a"', '"b"'])).toEqual([['a"b']]);
+});
+
+test("text after a closing quote is a SyntaxError, also a \\r split from its \\n", () => {
+  expect(() => viaStream(['"a"\r', "x"])).toThrow(SyntaxError);
+  expect(() => viaStream(['"a"\r'])).toThrow(SyntaxError);
+  expect(() => viaStream(['"a"', "b"])).toThrow(SyntaxError);
+});
+
+test("a quote in a field that is not quoted is a SyntaxError", () => {
+  expect(() => viaStream(["a", '"'])).toThrow(SyntaxError);
+});
+
+test("a quoted field still open at the end is a SyntaxError from end", () => {
+  const s = new CsvStream();
+  s.push('"ab');
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(viaStream(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(viaStream(["\uFEFF", "a"])).toEqual([["a"]]);
+  expect(viaStream(["a\uFEFF"])).toEqual([["a\uFEFF"]]);
+});
+
+test("empty input, a lone BOM and a row end at the end start no extra row", () => {
+  expect(new CsvStream().end()).toEqual([]);
+  expect(viaStream(["\uFEFF"])).toEqual([]);
+  expect(viaStream(["a\n"])).toEqual([["a"]]);
+  expect(viaStream(["a\n\nb"])).toEqual([["a"], [""], ["b"]]);
+  expect(viaStream(["a,"])).toEqual([["a", ""]]);
+});
+
+test("random inputs and random chunkings give the parseCsv rows", () => {
+  const rand = mulberry32(1);
+  for (let k = 0; k < 3000; k++) {
+    const len = Math.floor(rand() * 13);
+    let text = "";
+    for (let j = 0; j < len; j++) text += ALPHABET[Math.floor(rand() * ALPHABET.length)];
+    const cuts = Array.from({ length: Math.floor(rand() * 5) }, () => Math.floor(rand() * (len + 1))).sort((a, b) => a - b);
+    expectSameAsParse(text, splitAt(text, cuts));
+  }
+});
+
+test("every input of up to 4 characters, in 1 or 2 cuts and in 1-character chunks", () => {
+  const inputs = [""];
+  let level = [""];
+  for (let n = 1; n <= 4; n++) {
+    level = level.flatMap((p) => ALPHABET.map((c) => p + c));
+    inputs.push(...level);
+  }
+  for (const text of inputs) {
+    for (let a = 0; a <= text.length; a++) {
+      expectSameAsParse(text, splitAt(text, [a]));
+      for (let b = a; b <= text.length; b++) expectSameAsParse(text, splitAt(text, [a, b]));
+    }
+    expectSameAsParse(text, text.split(""));
+  }
+});
+
+test("a chunk costs the same however much input came before it", () => {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  rows.push(...s.push('"'));
+  for (let k = 0; k < 200_000; k++) rows.push(...s.push("x"));
+  rows.push(...s.push('"\n'));
+  for (let k = 0; k < 200_000; k++) rows.push(...s.push('"x\n"\n'));
+  rows.push(...s.end());
+  expect(rows.length).toBe(200_001);
+  expect(rows[0]?.[0]?.length).toBe(200_000);
+  expect(rows[1]).toEqual(["x\n"]);
+  expect(rows[200_000]).toEqual(["x\n"]);
+});
+
+test("after a SyntaxError every call rethrows that same error", () => {
+  const s = new CsvStream();
+  const first = thrown(() => s.push('a"'));
+  expect(first).toBeInstanceOf(SyntaxError);
+  expect(thrown(() => s.push("b"))).toBe(first);
+  expect(thrown(() => s.end())).toBe(first);
+});
+
+test("after end, push and end throw a plain Error", () => {
+  const s = new CsvStream();
+  s.push("a");
+  s.end();
+  const e = thrown(() => s.push("b"));
+  expect(e).toBeInstanceOf(Error);
+  expect(e).not.toBeInstanceOf(SyntaxError);
+  expect((e as Error).message).toBe("CsvStream has ended");
+  expect((thrown(() => s.end()) as Error).message).toBe("CsvStream has ended");
+});
+
+test("a SyntaxError names the same offset as parseCsv, counted from the start of the input", () => {
+  const text = '\uFEFFa,"b"c';
+  const expected = thrown(() => parseCsv(text)) as Error;
+  const got = thrown(() => viaStream(['\uFEFFa,"', 'b"c'])) as Error;
+  expect(got.message).toBe(expected.message);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 15:25:15.403789786 +0000
+++ b/csv.ts	2026-10-29 15:27:42.652494392 +0000
@@ -50,3 +50,154 @@
   rows.push(row);
   return rows;
 }
+
+const UNQUOTED_STOP = /[,\r\n"]/g;
+
+/**
+ * Parses CSV like `parseCsv`, from chunks. It keeps only the unfinished row and field. After a SyntaxError every call
+ * rethrows it, and after `end` every call throws.
+ */
+export class CsvStream {
+  private row: string[] = [];
+  private field = "";
+  private offset = 0;
+  private state: "bom" | "rowStart" | "fieldStart" | "unquoted" | "unquotedCr" | "quoted" | "quote" | "closed" | "closedCr" | "ended" = "bom";
+  private error?: SyntaxError;
+
+  push(chunk: string): string[][] {
+    this.check();
+    try {
+      return this.feed(chunk);
+    } catch (e) {
+      this.error = e as SyntaxError;
+      throw e;
+    }
+  }
+
+  end(): string[][] {
+    this.check();
+    try {
+      return this.finish();
+    } catch (e) {
+      this.error = e as SyntaxError;
+      throw e;
+    }
+  }
+
+  private check() {
+    if (this.error) throw this.error;
+    if (this.state === "ended") throw new Error("CsvStream has ended");
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "fieldStart";
+  }
+
+  private endRow(rows: string[][]) {
+    this.row.push(this.field);
+    rows.push(this.row);
+    this.row = [];
+    this.field = "";
+    this.state = "rowStart";
+  }
+
+  private feed(chunk: string): string[][] {
+    const rows: string[][] = [];
+    const base = this.offset;
+    this.offset += chunk.length;
+    let i = 0;
+    while (i < chunk.length) {
+      switch (this.state) {
+        case "bom":
+          if (chunk[i] === "\uFEFF") i++;
+          this.state = "rowStart";
+          break;
+        case "rowStart":
+        case "fieldStart":
+          if (chunk[i] === '"') {
+            this.state = "quoted";
+            i++;
+          } else this.state = "unquoted";
+          break;
+        case "unquoted": {
+          UNQUOTED_STOP.lastIndex = i;
+          const m = UNQUOTED_STOP.exec(chunk);
+          const stop = m ? m.index : chunk.length;
+          this.field += chunk.slice(i, stop);
+          i = stop;
+          if (!m) break;
+          const c = chunk[i++];
+          if (c === ",") this.endField();
+          else if (c === "\n") this.endRow(rows);
+          else if (c === "\r") this.state = "unquotedCr";
+          else throw new SyntaxError(`a quote in a field that is not quoted, at offset ${base + i - 1}`);
+          break;
+        }
+        case "unquotedCr":
+          if (chunk[i] === "\n") {
+            i++;
+            this.endRow(rows);
+          } else {
+            this.field += "\r";
+            this.state = "unquoted";
+          }
+          break;
+        case "quoted": {
+          const q = chunk.indexOf('"', i);
+          const stop = q === -1 ? chunk.length : q;
+          this.field += chunk.slice(i, stop);
+          i = stop;
+          if (q !== -1) {
+            i++;
+            this.state = "quote";
+          }
+          break;
+        }
+        case "quote":
+          if (chunk[i] === '"') {
+            this.field += '"';
+            this.state = "quoted";
+            i++;
+          } else this.state = "closed";
+          break;
+        case "closed": {
+          const c = chunk[i++];
+          if (c === ",") this.endField();
+          else if (c === "\n") this.endRow(rows);
+          else if (c === "\r") this.state = "closedCr";
+          else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${base + i - 1}`);
+          break;
+        }
+        case "closedCr":
+          if (chunk[i] !== "\n") throw new SyntaxError(`unexpected ${JSON.stringify("\r")} after a closing quote at offset ${base + i - 1}`);
+          i++;
+          this.endRow(rows);
+          break;
+      }
+    }
+    return rows;
+  }
+
+  private finish(): string[][] {
+    const rows: string[][] = [];
+    switch (this.state) {
+      case "bom":
+      case "rowStart":
+        break;
+      case "quoted":
+        throw new SyntaxError("a quoted field is still open at the end of the input");
+      case "closedCr":
+        throw new SyntaxError(`unexpected ${JSON.stringify("\r")} after a closing quote at offset ${this.offset - 1}`);
+      case "unquotedCr":
+        this.field += "\r";
+        this.endRow(rows);
+        break;
+      default:
+        this.endRow(rows);
+    }
+    this.state = "ended";
+    return rows;
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 15:28:13.122941387 +0000
@@ -0,0 +1,157 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function rowsOf(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+function lcg(seed: number) {
+  let s = seed >>> 0;
+  return (n: number) => {
+    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
+    return (s >>> 8) % n;
+  };
+}
+
+function randomChunks(input: string, rnd: (n: number) => number): string[] {
+  const chunks: string[] = [];
+  let cur = "";
+  for (const ch of input) {
+    if (rnd(5) === 0) {
+      chunks.push(cur);
+      cur = "";
+    }
+    if (rnd(6) === 0) chunks.push("");
+    cur += ch;
+  }
+  chunks.push(cur);
+  return chunks;
+}
+
+function outcome(input: string, chunks: string[]) {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  try {
+    for (const c of chunks) rows.push(...s.push(c));
+    rows.push(...s.end());
+    return { rows, error: undefined };
+  } catch (e) {
+    return { rows: [], error: e instanceof SyntaxError ? "SyntaxError" : String(e) };
+  }
+}
+
+function expectSameAsParseCsv(input: string, chunks: string[]) {
+  let want: { rows: string[][]; error: string | undefined };
+  try {
+    want = { rows: parseCsv(input), error: undefined };
+  } catch (e) {
+    want = { rows: [], error: e instanceof SyntaxError ? "SyntaxError" : String(e) };
+  }
+  expect({ input, chunks, ...outcome(input, chunks) }).toEqual({ input, chunks, ...want });
+}
+
+test("commas separate fields and a row ends at \\n", () => {
+  expect(rowsOf(["a,b\n"])).toEqual([["a", "b"]]);
+});
+
+test("a \\r\\n split across chunks ends the row once the \\n arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a \\r that is not followed by \\n is part of its field", () => {
+  expect(rowsOf(["a\r", "b"])).toEqual([["a\rb"]]);
+  expect(rowsOf(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a quoted field can hold , \\r and \\n and doubled quotes, even split across chunks", () => {
+  expect(rowsOf(['"x', '"', '"y,\r\n"', "\n"])).toEqual([['x"y,\r\n']]);
+  expect(rowsOf(['"a""', '"\n'])).toEqual([['a"']]);
+});
+
+test("a closing quote must be followed by a comma, a row end or the end of input", () => {
+  expect(() => rowsOf(['"a"', "b"])).toThrow(SyntaxError);
+  const s = new CsvStream();
+  expect(s.push('"a"\r')).toEqual([]);
+  expect(() => s.push("x")).toThrow(SyntaxError);
+  expect(() => rowsOf(['"a"\r'])).toThrow(SyntaxError);
+  expect(rowsOf(['"a"'])).toEqual([["a"]]);
+});
+
+test("a quote in a field that is not quoted is a SyntaxError", () => {
+  expect(() => new CsvStream().push('a"')).toThrow(SyntaxError);
+  expect(() => rowsOf(["a,b\r", '"c'])).toThrow(SyntaxError);
+});
+
+test("a quoted field still open at the end of the input is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(s.push('"ab')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(rowsOf(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(rowsOf(["a", "\uFEFFb"])).toEqual([["a\uFEFFb"]]);
+  expect(rowsOf(["\uFEFF"])).toEqual([]);
+});
+
+test("empty input has no rows and a trailing row end adds none", () => {
+  expect(rowsOf([])).toEqual([]);
+  expect(rowsOf([""])).toEqual([]);
+  expect(rowsOf(["a\n"])).toEqual([["a"]]);
+  expect(rowsOf(["a,"])).toEqual([["a", ""]]);
+  expect(rowsOf(["a\n\nb"])).toEqual([["a"], [""], ["b"]]);
+});
+
+test("the rows from all calls equal parseCsv for random inputs and random splits", () => {
+  const rnd = lcg(42);
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  for (let n = 0; n < 3000; n++) {
+    let input = "";
+    const len = rnd(13);
+    for (let k = 0; k < len; k++) input += alphabet[rnd(alphabet.length)];
+    expectSameAsParseCsv(input, randomChunks(input, rnd));
+    expectSameAsParseCsv(input, [...input]);
+    if (input.length <= 8) {
+      for (let mask = 0; mask < 1 << (input.length - 1); mask++) {
+        const chunks: string[] = [];
+        let cur = "";
+        for (let k = 0; k < input.length; k++) {
+          if (k > 0 && mask & (1 << (k - 1))) {
+            chunks.push(cur);
+            cur = "";
+          }
+          cur += input[k];
+        }
+        chunks.push(cur);
+        expectSameAsParseCsv(input, chunks);
+      }
+    }
+  }
+});
+
+test("a long field and many rows fed in one-char chunks match parseCsv", () => {
+  const rows = Array.from({ length: 20000 }, (_, i) => `${i},y\n`).join("");
+  const input = `"${"x".repeat(200000)}"\n${rows}`;
+  expect(rowsOf([...input])).toEqual(parseCsv(input));
+});
+
+test("after a SyntaxError every later call throws it again", () => {
+  const s = new CsvStream();
+  expect(() => s.push('a"')).toThrow(SyntaxError);
+  expect(() => s.push("b\n")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("after end() push and end throw an Error", () => {
+  const s = new CsvStream();
+  expect(s.end()).toEqual([]);
+  expect(() => s.push("a")).toThrow("CsvStream already ended");
+  expect(() => s.end()).toThrow("CsvStream already ended");
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 15:25:15.412957913 +0000
+++ b/csv.ts	2026-10-29 15:27:56.088702874 +0000
@@ -50,3 +50,145 @@
   rows.push(row);
   return rows;
 }
+
+type StreamState = "rowStart" | "fieldStart" | "plain" | "quoted" | "quote" | "closed";
+
+const plainStop = /[,\r\n"]/g;
+
+/**
+ * parseCsv read in chunks. It keeps only the current row, the partial field and where the parse stands, so the work
+ * for a chunk depends on the chunk alone. push returns the rows whose row end has arrived, end returns the rest once
+ * the input is over. A SyntaxError is kept and thrown again by every later call; a call after end() throws an Error.
+ */
+export class CsvStream {
+  private row: string[] = [];
+  private field = "";
+  private state: StreamState = "rowStart";
+  private crAt = -1; // absolute offset of a \r whose meaning waits for the next char, or -1
+  private offset = 0; // absolute offset of the first char of the next chunk
+  private started = false;
+  private ended = false;
+  private error: SyntaxError | undefined;
+
+  push(chunk: string): string[][] {
+    this.guard();
+    const base = this.offset;
+    this.offset += chunk.length;
+    const rows: string[][] = [];
+    let i = 0;
+    if (!this.started && chunk !== "") {
+      this.started = true;
+      if (chunk[0] === "\uFEFF") i = 1;
+    }
+    while (i < chunk.length) {
+      if (this.crAt >= 0) {
+        if (chunk[i] === "\n") {
+          this.crAt = -1;
+          i++;
+          this.endRow(rows);
+        } else if (this.state === "closed") {
+          throw this.fail(`unexpected "\\r" after a closing quote at offset ${this.crAt}`);
+        } else {
+          this.crAt = -1;
+          this.field += "\r";
+        }
+        continue;
+      }
+      switch (this.state) {
+        case "quoted": {
+          const q = chunk.indexOf('"', i);
+          if (q < 0) {
+            this.field += chunk.slice(i);
+            i = chunk.length;
+          } else {
+            this.field += chunk.slice(i, q);
+            i = q + 1;
+            this.state = "quote";
+          }
+          break;
+        }
+        case "quote":
+          if (chunk[i] === '"') {
+            this.field += '"';
+            this.state = "quoted";
+            i++;
+          } else this.state = "closed";
+          break;
+        case "closed": {
+          const c = chunk[i]!;
+          if (c === ",") this.endField();
+          else if (c === "\n") this.endRow(rows);
+          else if (c === "\r") this.crAt = base + i;
+          else throw this.fail(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${base + i}`);
+          i++;
+          break;
+        }
+        default: {
+          if (this.state === "plain") {
+            plainStop.lastIndex = i;
+            const m = plainStop.exec(chunk);
+            const stop = m ? m.index : chunk.length;
+            this.field += chunk.slice(i, stop);
+            i = stop;
+            if (i === chunk.length) break;
+          }
+          const c = chunk[i]!;
+          if (c === ",") {
+            this.endField();
+            i++;
+          } else if (c === "\n") {
+            this.endRow(rows);
+            i++;
+          } else if (c === "\r") {
+            this.crAt = base + i;
+            this.state = "plain";
+            i++;
+          } else if (c === '"') {
+            if (this.state === "plain") throw this.fail(`a quote in a field that is not quoted, at offset ${base + i}`);
+            this.state = "quoted";
+            i++;
+          } else this.state = "plain";
+        }
+      }
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    this.guard();
+    this.ended = true;
+    if (this.state === "quoted") throw this.fail("a quoted field is still open at the end of the input");
+    if (this.crAt >= 0) {
+      if (this.state === "closed") throw this.fail(`unexpected "\\r" after a closing quote at offset ${this.crAt}`);
+      this.crAt = -1;
+      this.field += "\r";
+    }
+    if (this.state === "rowStart") return [];
+    this.row.push(this.field);
+    return [this.row];
+  }
+
+  private guard() {
